back": {"correct": "Right! 가 ends in a vowel, so it takes 세요."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"Please read the book.\" Split the verb and (으)세요. 읽 ends in a consonant, so use 으세요.", "contentObj": {"sentence": "책을 읽으세요.", "translation": "Please read the book.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["책을"], "correct_turtle": ["책을"], "turtle_explanation": "Keep '책을' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["읽으세요"], "correct_turtle": ["읽", "으세요"], "turtle_explanation": "'으세요' asks someone politely to do it. After a consonant use 으세요, after a vowel use 세요."}], "options": [{"id": "o1", "text": "세요", "mode": "turtle"}, {"id": "o2", "text": "책을", "mode": "turtle"}, {"id": "o3", "text": "으세요", "mode": "turtle"}, {"id": "o4", "text": "책을", "mode": "rabbit"}, {"id": "o5", "text": "읽", "mode": "turtle"}, {"id": "o6", "text": "읽으세요", "mode": "rabbit"}, {"id": "o7", "text": "읽세요", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"Please drink water.\" Split the verb and (으)세요.", "contentObj": {"sentence": "물을 마시세요.", "translation": "Please drink water.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["물을"], "correct_turtle": ["물을"], "turtle_explanation": "Keep '물을' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["마시세요"], "correct_turtle": ["마시", "세요"], "turtle_explanation": "'세요' asks someone politely to do it. After a consonant use 으세요, after a vowel use 세요."}], "options": [{"id": "o1", "text": "으세요", "mode": "turtle"}, {"id": "o2", "text": "마시", "mode": "turtle"}, {"id": "o3", "text": "마시세요", "mode": "rabbit"}, {"id": "o4", "text": "물을", "mode": "rabbit"}, {"id": "o5", "text": "세요", "mode": "turtle"}, {"id": "o6", "text": "마시으세요", "mode": "rabbit"}, {"id": "o7", "text": "물을", 